const data = $json;

const product_url = data["Product URL"] || '';
const product_doc_text = data["Product Details"] || '';
const product_image_url = data["Product Image URL"] || '';
const brand_name = data["Brand Name"] || 'Skincare Brand';

const target_audience =
  data["Target Audience"] && data["Target Audience"].trim() !== ''
    ? data["Target Audience"].trim()
    : 'Skincare buyers in India';

const cta =
  data["CTA"] && data["CTA"].trim() !== ''
    ? data["CTA"].trim()
    : 'Shop Now';

const ad_style =
  data["Ad Style"] && data["Ad Style"].trim() !== ''
    ? `${data["Ad Style"].trim()}, skincare-focused, hyper-realistic, vertical 9:16 Instagram Reel`
    : 'premium skincare commercial, skincare-focused, hyper-realistic, vertical 9:16 Instagram Reel';

// Supports both corrected and old misspelled form field names
const model_preference_raw = data["Model Preference"] || data["Model Peference"] || '';
const model_preference =
  model_preference_raw && model_preference_raw.trim() !== ''
    ? model_preference_raw.trim()
    : 'Let AI decide';

const generation_mode =
  data["Generation Mode"] && data["Generation Mode"].trim() !== ''
    ? data["Generation Mode"].trim()
    : 'Test - 1 scene only';

const scene_limit = generation_mode.toLowerCase().includes('full') ? 5 : 1;

return [
  {
    json: {
      product_url,
      product_doc_text,
      product_image_url,
      brand_name,
      target_audience,
      cta,
      category: 'skincare',
      ad_style,
      model_preference,
      generation_mode,
      scene_limit,
      request_id: Date.now().toString()
    }
  }
];

let rawResponse = '';

if (Array.isArray($json.output)) {
  for (const outputItem of $json.output) {
    if (Array.isArray(outputItem.content)) {
      const textItem = outputItem.content.find(c => c.type === 'output_text' && c.text);
      if (textItem) {
        rawResponse = textItem.text;
        break;
      }
    }
  }
}

if (!rawResponse) {
  rawResponse = $json.output_text || $json.text || '';
}

if (typeof rawResponse !== 'string') {
  rawResponse = JSON.stringify(rawResponse);
}

const cleaned = rawResponse
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

let plan;

try {
  plan = JSON.parse(cleaned);
} catch (e) {
  throw new Error('AI Creative Brain did not return valid JSON: ' + cleaned);
}

if (!plan.scenes || !Array.isArray(plan.scenes)) {
  throw new Error('No scenes array found in AI response');
}

const sceneLimit = Math.max(1, Math.min(5, Number($('2. Normalize Inputs').item.json.scene_limit || 1)));
let scenes = plan.scenes.slice(0, sceneLimit);

while (scenes.length < sceneLimit) {
  scenes.push({
    scene_number: scenes.length + 1,
    duration: 5,
    scene_title: 'Fallback Product Shot',
    video_prompt:
      'vertical 9:16, hyper-realistic skincare commercial, preserve exact product packaging from reference image, do not redesign label or bottle, product on clean background, soft lighting, slow push-in camera movement, premium studio environment, premium aesthetic'
  });
}

const productImageUrl = $('2. Normalize Inputs').item.json.product_image_url;
const requestId = $('2. Normalize Inputs').item.json.request_id;

return scenes.map((scene, index) => {
  let safePrompt = scene.video_prompt
    ? scene.video_prompt
    : 'vertical 9:16, hyper-realistic skincare product shot, preserve exact product packaging from reference image, do not redesign label or bottle, clean aesthetic';

  if (!safePrompt.includes('preserve exact product packaging')) {
    safePrompt = `vertical 9:16, hyper-realistic skincare commercial, preserve exact product packaging from reference image, do not redesign label or bottle, ${safePrompt}`;
  }

  return {
    json: {
      request_id: requestId,
      product_image_url: productImageUrl,
      scene_number: index + 1,
      duration: 5,
      scene_title: scene.scene_title || `Scene ${index + 1}`,
      video_prompt: safePrompt,
      full_plan: plan,
      generation_mode: $('2. Normalize Inputs').item.json.generation_mode,
      scene_limit: sceneLimit
    }
  };
});

const items = $input.all();

const videoUrls = items.map(item => {
  return item.json.drive_url || item.json.webContentLink || item.json.webViewLink || (item.json.id ? `https://drive.google.com/file/d/${item.json.id}/view` : '');
}).filter(Boolean);

if (videoUrls.length === 0) {
  throw new Error('No Google Drive video URLs found');
}

const firstItem = items[0].json;
const firstPlan = firstItem.full_plan || $('5. Split Into 5 Scenes').first().json.full_plan;

return [{
  json: {
    request_id: $('2. Normalize Inputs').item.json.request_id,
    brand_name: $('2. Normalize Inputs').item.json.brand_name,
    product_image_url: $('2. Normalize Inputs').item.json.product_image_url,
    generation_mode: $('2. Normalize Inputs').item.json.generation_mode,
    scene_limit: $('2. Normalize Inputs').item.json.scene_limit,
    video_urls: videoUrls,
    full_plan: firstPlan,
    voiceover_script: firstPlan.voiceover_script,
    caption_text: firstPlan.caption_text,
    final_cta: firstPlan.final_cta
  }
}];

const voiceoverDriveFile = $json;
const data = $('10B. Collect Scene Video URLs').item.json;

return [
  {
    json: {
      status: 'completed_for_review',
      message: 'MVP output generated. Scene videos and voiceover are saved in Google Drive.',
      request_id: data.request_id,
      brand_name: data.brand_name,
      generation_mode: data.generation_mode,
      scene_limit: data.scene_limit,
      product_image_url: data.product_image_url,
      scene_video_urls: data.video_urls,
      voiceover_google_drive_response: voiceoverDriveFile,
      caption_text: data.caption_text,
      final_cta: data.final_cta,
      creative_plan: data.full_plan
    }
  }
];

const upload = $json;
const scene = $('5. Split Into 5 Scenes').item.json;

const driveUrl =
  upload.webViewLink ||
  upload.webContentLink ||
  (upload.id ? `https://drive.google.com/file/d/${upload.id}/view` : '');

const safeSceneTitle = scene.scene_title || `Scene ${scene.scene_number}`;

return [
  {
    json: {
      ...upload,
      request_id: scene.request_id,
      scene_number: scene.scene_number,
      scene_title: safeSceneTitle,
      product_image_url: scene.product_image_url,
      drive_url: driveUrl,
      full_plan: scene.full_plan,
      telegram_message: `✅ Scene ${scene.scene_number} uploaded to Google Drive\n\nScene: ${safeSceneTitle}\nRequest ID: ${scene.request_id}\nDrive File: ${driveUrl || upload.id || 'Uploaded, but no link returned'}`
    }
  }
];
